// Gehzeiten in Minuten
// Schule  – Bahnhof   4
// Schule  – Park      2
// Park    – Bahnhof   1
// Bahnhof – Kino      5
// Park    – Kino      8
// Kino    – Freibad   3
var netz = new Dictionary<string,
    List<(string Ziel, int Min)>>();

void Weg(string a, string b, int min)
{
    if (!netz.ContainsKey(a)) netz[a] = new();
    if (!netz.ContainsKey(b)) netz[b] = new();
    netz[a].Add((b, min));
    netz[b].Add((a, min));
}
Weg("Schule", "Bahnhof", 4);
Weg("Schule", "Park", 2);
// ... restliche Wege genauso

var pq = new PriorityQueue<string, int>();
pq.Enqueue("Kino", 9);
pq.Enqueue("Park", 2);
pq.Enqueue("Bahnhof", 4);

Console.WriteLine(pq.Peek());   // Park
while (pq.Count > 0)
    Console.Write(pq.Dequeue() + " ");
// Park Bahnhof Kino

var dist = new Dictionary<string, int>();
var vorg = new Dictionary<string, string>();
foreach (var k in netz.Keys)
    dist[k] = int.MaxValue;
dist["Schule"] = 0;

var pq = new PriorityQueue<string, int>();
pq.Enqueue("Schule", 0);

while (pq.TryDequeue(out string u, out int d))
{
    if (d > dist[u]) continue; // veraltet
    foreach (var (v, w) in netz[u])
    {
        int neu = d + w;
        if (neu < dist[v])
        {
            dist[v] = neu;
            vorg[v] = u;
            pq.Enqueue(v, neu);
        }
    }
}
// Schule: 0   Bahnhof: 3   Park: 2
// Kino: 8     Freibad: 11

var weg = new List<string>();
for (string k = "Freibad"; k != null;
     k = vorg.GetValueOrDefault(k))
    weg.Add(k);
weg.Reverse();
Console.WriteLine(string.Join(" -> ", weg));
// Schule -> Park -> Bahnhof -> Kino
//   -> Freibad

